#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic)
# check_split.sh <container> — while a split run is in progress, print the CPU
# affinity of the key processes inside the container so the P/E split can be
# verified: application (ros2 launch, component containers, bag play, nsys)
# must sit on FISH_APP_CPUS, the observer (lttng-sessiond/consumerd, FISH
# daemon, probes) on FISH_OBS_CPUS.
C=${1:?container name}
docker exec "$C" bash -c '
  echo "container cpuset : $(cat /sys/fs/cgroup/cpuset.cpus.effective 2>/dev/null)"
  printf "%-8s %-22s %-14s %s\n" PID COMM AFFINITY CMD
  for pat in "lttng-sessiond" "lttng-consumerd" "fish.cli gpu daemon" "ros2 launch" "ros2 bag play" "nsys profile" "component_container" "topic echo" "multi_object_tracker" "shape_estimation_node" "detection_by_tracker_node"; do
    for pid in $(pgrep -f "$pat" | head -4); do
      [ -r /proc/$pid/status ] || continue
      grep -qE "for pat in|PROBE_FN" /proc/$pid/cmdline 2>/dev/null && continue   # skip this checker + the run-script shell
      aff=$(taskset -pc $pid 2>/dev/null | sed "s/.*: //")
      printf "%-8s %-22s %-14s %s\n" "$pid" "$(cat /proc/$pid/comm)" "$aff" "$(tr "\0\n" "  " < /proc/$pid/cmdline | cut -c1-70)"
    done
  done
  latest=$(ls -td /root/fish_traces/fish_2026* 2>/dev/null | head -1)
  echo "--- daemon kill/resurrect in $latest: $(grep -cE " (kill|resurrect) " $latest/fishlog/fish_events_*.log 2>/dev/null)"
'
